import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';

export default function SellerLogin({ onClose }) {
    const navigate = useNavigate();
    const [loginData, setLoginData] = useState({
        email: '',
        password: ''
    });
    const [showPassword, setShowPassword] = useState(false);
    const [step, setStep] = useState(1); // 1: email check, 2: password entry, 3: set password
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        // Initialize icons if lucide is available
        if (window.lucide) {
            window.lucide.createIcons();
        }
    }, []);

    const handleEmailSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.email) {
            toast.error('Please enter your email');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/seller/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ email: loginData.email })
            });
            
            const data = await response.json();
            
            if (data.success) {
                if (data.needsPassword) {
                    if (data.data && data.data.needsPasswordSetup) {
                        setStep(3); // Set password
                    } else {
                        setStep(2); // Enter password
                    }
                } else {
                    // Login successful, store user data and redirect
                    localStorage.setItem('studioToken', 'simulated-token');
                    localStorage.setItem('studioUser', JSON.stringify({
                        id: data.data.id,
                        email: data.data.email,
                        firstName: data.data.firstname,
                        lastName: data.data.lastname,
                        role: 'seller'
                    }));
                    toast.success('Login successful');
                    if (onClose) onClose();
                    navigate('/studio/seller');
                }
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Login error:', error);
            toast.error('Login failed: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.password) {
            toast.error('Please enter your password');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/seller/login-with-password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ 
                    email: loginData.email,
                    password: loginData.password
                })
            });
            
            const data = await response.json();
            
            if (data.success) {
                // Login successful, store user data and redirect
                localStorage.setItem('studioToken', 'simulated-token');
                localStorage.setItem('studioUser', JSON.stringify({
                    id: data.data.id,
                    email: data.data.email,
                    firstName: data.data.firstname,
                    lastName: data.data.lastname,
                    role: 'seller'
                }));
                toast.success('Login successful');
                if (onClose) onClose();
                navigate('/studio/seller');
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Login error:', error);
            toast.error('Login failed: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handleSetPasswordSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.password) {
            toast.error('Please enter a password');
            return;
        }

        if (loginData.password.length < 6) {
            toast.error('Password must be at least 6 characters long');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/seller/set-password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ 
                    email: loginData.email,
                    password: loginData.password
                })
            });
            
            const data = await response.json();
            
            if (data.success) {
                toast.success('Password set successfully. Please login with your password.');
                setStep(2); // Go to password entry step
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Set password error:', error);
            toast.error('Failed to set password: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const renderEmailForm = () => (
        <form onSubmit={handleEmailSubmit} className="authentication-form">
            <div className="mb-3">
                <label className="form-label" htmlFor="UserEmail">Email Address</label>
                <div className="position-relative">
                    <input 
                        type="email" 
                        className="form-control form-control-lg" 
                        id="UserEmail" 
                        name="email"
                        placeholder="Enter your email" 
                        value={loginData.email}
                        onChange={(e) => setLoginData({...loginData, email: e.target.value})}
                        disabled={loading}
                        required 
                    />
                    <span className="text-muted position-absolute end-0 top-50 translate-middle-y me-3">
                        <i className="fas fa-envelope"></i>
                    </span>
                </div>
            </div>
            <div className="d-grid">
                <button 
                    className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium" 
                    type="submit"
                    disabled={loading}
                >
                    {loading ? (
                        <>
                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                            Verifying...
                        </>
                    ) : (
                        <>
                            <i className="fas fa-arrow-right"></i> Continue
                        </>
                    )}
                </button>
            </div>
        </form>
    );

    const renderPasswordForm = () => (
        <form onSubmit={handlePasswordSubmit} className="authentication-form">
            <div className="mb-3">
                <label className="form-label" htmlFor="UserEmail">Email</label>
                <div className="input-group">
                    <input 
                        type="email" 
                        className="form-control" 
                        id="UserEmail" 
                        value={loginData.email}
                        disabled
                    />
                    <button 
                        className="btn btn-outline-secondary" 
                        type="button"
                        onClick={() => setStep(1)}
                    >
                        Change
                    </button>
                </div>
            </div>
            
            <div className="mb-3">
                <div className="d-flex justify-content-between">
                    <label className="form-label" htmlFor="UserPass">Password</label>
                    <a href="#" className="text-muted small">Forgot password?</a>
                </div>
                <div className="position-relative">
                    <input 
                        type={showPassword ? "text" : "password"}
                        className="form-control form-control-lg" 
                        id="UserPass" 
                        name="password"
                        placeholder="Enter your password" 
                        value={loginData.password}
                        onChange={(e) => setLoginData({...loginData, password: e.target.value})}
                        disabled={loading}
                        required 
                    />
                    <button
                        type="button"
                        className="btn text-muted position-absolute end-0 top-50 translate-middle-y me-3"
                        onClick={() => setShowPassword(!showPassword)}
                    >
                        <i className={showPassword ? "fas fa-eye-slash" : "fas fa-eye"}></i>
                    </button>
                </div>
            </div>
            
            <div className="form-check mb-3">
                <input type="checkbox" className="form-check-input" id="rememberMe" />
                <label className="form-check-label small" htmlFor="rememberMe">Remember me</label>
            </div>
            
            <div className="d-grid">
                <button 
                    className="btn btn-success d-flex align-items-center justify-content-center gap-1 fw-medium" 
                    type="submit"
                    disabled={loading}
                >
                    {loading ? (
                        <>
                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                            Signing in...
                        </>
                    ) : (
                        <>
                            <i className="fas fa-sign-in-alt"></i> Sign In
                        </>
                    )}
                </button>
            </div>
        </form>
    );

    const renderSetPasswordForm = () => (
        <form onSubmit={handleSetPasswordSubmit} className="authentication-form">
            <div className="alert alert-info small">
                <p className="mb-0">
                    <i className="fas fa-info-circle me-1"></i>
                    Welcome! Please set your password to complete your seller account setup.
                </p>
            </div>
            
            <div className="mb-3">
                <label className="form-label" htmlFor="UserEmail">Email</label>
                <div className="input-group">
                    <input 
                        type="email" 
                        className="form-control" 
                        id="UserEmail" 
                        value={loginData.email}
                        disabled
                    />
                    <button 
                        className="btn btn-outline-secondary" 
                        type="button"
                        onClick={() => setStep(1)}
                    >
                        Change
                    </button>
                </div>
            </div>
            
            <div className="mb-3">
                <label className="form-label" htmlFor="newPassword">New Password</label>
                <div className="position-relative">
                    <input 
                        type={showPassword ? "text" : "password"}
                        className="form-control form-control-lg" 
                        id="newPassword" 
                        name="password"
                        placeholder="Enter your new password" 
                        value={loginData.password}
                        onChange={(e) => setLoginData({...loginData, password: e.target.value})}
                        disabled={loading}
                        required 
                    />
                    <button
                        type="button"
                        className="btn text-muted position-absolute end-0 top-50 translate-middle-y me-3"
                        onClick={() => setShowPassword(!showPassword)}
                    >
                        <i className={showPassword ? "fas fa-eye-slash" : "fas fa-eye"}></i>
                    </button>
                </div>
                <div className="form-text small">Password must be at least 6 characters long</div>
            </div>
            
            <div className="d-grid">
                <button 
                    className="btn btn-success d-flex align-items-center justify-content-center gap-1 fw-medium" 
                    type="submit"
                    disabled={loading}
                >
                    {loading ? (
                        <>
                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                            Setting Password...
                        </>
                    ) : (
                        <>
                            <i className="fas fa-check-circle"></i> Set Password
                        </>
                    )}
                </button>
            </div>
        </form>
    );

    return (
        <div className="container">
            <div className="row justify-content-center">
                <div className="col-12">
                    <div className="text-center mb-3">
                        <h5 className="fw-bold text-dark">
                            {step === 1 && "Seller Login"}
                            {step === 2 && "Enter Password"}
                            {step === 3 && "Set Password"}
                        </h5>
                        <p className="text-muted small">
                            {step === 1 && "Enter your email to verify your seller account"}
                            {step === 2 && "Enter your password to login"}
                            {step === 3 && "Set your password to complete setup"}
                        </p>
                    </div>
                    
                    <div className="card border-0 shadow-sm">
                        <div className="card-body p-3">
                            {step === 1 && renderEmailForm()}
                            {step === 2 && renderPasswordForm()}
                            {step === 3 && renderSetPasswordForm()}
                            
                            <div className="text-center mt-3 pt-2 border-top">
                                <p className="mb-0 small">
                                    Don't have an account?{' '}
                                    <button
                                        className="btn btn-link p-0 text-primary small"
                                        onClick={() => {
                                            if (onClose) onClose();
                                            window.dispatchEvent(new CustomEvent('openLoginModal', { detail: 'seller-apply-for-reels' }));
                                        }}
                                    >
                                        Apply for Reels
                                    </button>
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
